insert into community_knowledge_sources
(slug,title,source_kind,coverage,make,model,subsystem,description,safety_note,tags,source_url,preview_url,attribution_author,license_code,license_url,rights_verified_on,technical_status) values
('common-rail-overview','Common Rail: базовая схема подачи топлива','diagram','generic',null,null,'Топливная система','Общий принцип: подача топлива под высоким давлением к общей рампе и управляемым форсункам. Сопоставляйте только функции узлов; размещение датчиков и магистралей зависит от исполнения.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['common rail','diesel','топливо','рампа','форсунка','ТНВД']::text[],'https://commons.wikimedia.org/wiki/File:Common_Rail_Scheme.svg','https://commons.wikimedia.org/wiki/Special:FilePath/Common_Rail_Scheme.svg','Smakkeloep','PUBLIC_DOMAIN','https://creativecommons.org/publicdomain/mark/1.0/',date '2026-11-17','illustrative'),
('cooling-liquid-engine','Жидкостное охлаждение ДВС: помпа, термостат, радиатор','diagram','generic',null,null,'Охлаждение','Обобщённый контур циркуляции охлаждающей жидкости с насосом, термостатом и теплообменником. Реальный обходной путь, количество термостатов и расположение датчиков могут отличаться.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['антифриз','помпа','термостат','радиатор','охлаждение']::text[],'https://commons.wikimedia.org/wiki/File:Uk%C5%82ad_ch%C5%82odzenia_silnika_spalinowego.svg','https://commons.wikimedia.org/wiki/Special:FilePath/Uk%C5%82ad_ch%C5%82odzenia_silnika_spalinowego.svg','Harkonnen2','CC-BY-SA-2.5','https://creativecommons.org/licenses/by-sa/2.5/',date '2026-11-17','illustrative'),
('diesel-scr-aftertreatment','Дизельный SCR и AdBlue: последовательность узлов','diagram','generic',null,null,'Выхлоп / SCR','Общая принципиальная цепочка обработки выхлопа дизеля с катализатором окисления, подачей мочевины и SCR. Не содержит схемы дозатора, точных датчиков NOx и параметров конкретного автомобиля.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['scr','adblue','евро6','nox','катализатор','выхлоп','сажевый фильтр']::text[],'https://commons.wikimedia.org/wiki/File:Diesel_tech.png','https://commons.wikimedia.org/wiki/Special:FilePath/Diesel_tech.png','Hastdutoene','CC-BY-SA-3.0','https://creativecommons.org/licenses/by-sa/3.0/',date '2026-11-17','illustrative'),
('differential-gear','Дифференциал ведущего моста: устройство','diagram','generic',null,null,'Трансмиссия / мост','Иллюстрация шестерён дифференциала и передачи крутящего момента на полуоси. Схема не определяет передаточное число, тип блокировки или заводской порядок регулировки зазоров.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['дифференциал','мост','редуктор','полуоси','трансмиссия']::text[],'https://commons.wikimedia.org/wiki/File:Differential_gear_(PSF).png','https://commons.wikimedia.org/wiki/Special:FilePath/Differential_gear_(PSF).png','Pearson Scott Foresman','PUBLIC_DOMAIN','https://creativecommons.org/publicdomain/mark/1.0/',date '2026-11-17','illustrative'),
('alternator-rotor-stator','Генератор: ротор, статор и образование напряжения','diagram','generic',null,null,'Электрика / зарядка','Общий принцип генерации переменного напряжения при вращении магнитного поля относительно обмоток статора. Реальная автомобильная система включает выпрямитель, регулятор, возбуждение и иную разводку.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['генератор','ротор','статор','зарядка','электрика']::text[],'https://commons.wikimedia.org/wiki/File:Alternator_1.svg','https://commons.wikimedia.org/wiki/Special:FilePath/Alternator_1.svg','Egmason','CC-BY-3.0','https://creativecommons.org/licenses/by/3.0/',date '2026-11-17','illustrative'),
('diesel-valve-phasing','Четырёхтактный дизель: моменты открытия клапанов и впрыска','diagram','generic',null,null,'Двигатель / ГРМ','Учебная диаграмма фаз работы четырёхтактного дизеля. НЕ является установочными метками ГРМ, углами впрыска или картой калибровки Renault, Volvo, Scania и других двигателей.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['дизель','грм','фазы','впрыск','клапаны','поршень']::text[],'https://commons.wikimedia.org/wiki/File:Indicator_diagram_four_stroke_diesel.svg','https://commons.wikimedia.org/wiki/Special:FilePath/Indicator_diagram_four_stroke_diesel.svg','BoH','CC-BY-SA-3.0','https://creativecommons.org/licenses/by-sa/3.0/',date '2026-11-17','illustrative'),
('brake-air-disc-example','Пневматический дисковый тормоз грузовика: внешний вид','photo','generic',null,null,'Тормоза / пневматика','Фотография узла пневмоприводного дискового тормоза грузового автомобиля. Иллюстрирует тип изделия, но не заменяет схему пневмомагистралей, EBS или методику безопасной разборки.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['тормоз','пневматика','суппорт','диск','ebs']::text[],'https://commons.wikimedia.org/wiki/File:Air_disc_brake.jpg','https://commons.wikimedia.org/wiki/Special:FilePath/Air_disc_brake.jpg','Panoha','CC-BY-SA-3.0','https://creativecommons.org/licenses/by-sa/3.0/',date '2026-11-17','illustrative'),
('diesel-four-stroke-animation','Четырёхтактный дизель: анимация рабочего цикла','diagram','generic',null,null,'Двигатель / цикл','Анимация последовательности впуска, сжатия, рабочего хода и выпуска в дизельном двигателе. Схематическая модель без данных о конкретном блоке, ЭБУ и метках механизма.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['дизель','двигатель','цикл','поршень','клапаны']::text[],'https://commons.wikimedia.org/wiki/File:Four_stroke_diesel_engine_animation.gif','https://commons.wikimedia.org/wiki/Special:FilePath/Four_stroke_diesel_engine_animation.gif','Alexanderathomas','CC-BY-SA-3.0','https://creativecommons.org/licenses/by-sa/3.0/',date '2026-11-17','illustrative'),
('engine-pv-diagram','Диаграмма давление–объём четырёхтактного двигателя','diagram','generic',null,null,'Двигатель / цикл','Учебная p-V диаграмма для понимания циклов сжатия, расширения и выпуска. Нельзя применять значения с рисунка как диагностические нормы давления для конкретного мотора.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['давление','объём','диаграмма','двигатель','компрессия']::text[],'https://commons.wikimedia.org/wiki/File:P-v_diagram_four_stroke_piston_engine.svg','https://commons.wikimedia.org/wiki/Special:FilePath/P-v_diagram_four_stroke_piston_engine.svg','Olivier Cleynen','CC0-1.0','https://creativecommons.org/publicdomain/zero/1.0/',date '2026-11-17','illustrative'),
('diesel-pv-diagram','p-V диаграмма дизельного цикла','diagram','generic',null,null,'Двигатель / цикл','Упрощённая диаграмма давления и объёма четырёхтактного дизеля. Реальная индикаторная диаграмма и давление цилиндра существенно зависят от конкретной конструкции и нагрузки.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['дизель','pv','давление','объём','компрессия']::text[],'https://commons.wikimedia.org/wiki/File:PV_diesel.gif','https://commons.wikimedia.org/wiki/Special:FilePath/PV_diesel.gif','MyName (Armchoir)','PUBLIC_DOMAIN','https://creativecommons.org/publicdomain/mark/1.0/',date '2026-11-17','illustrative'),
('differential-geartrain','Шестерёнчатая передача: учебная схема','diagram','generic',null,null,'Трансмиссия / мост','Общая иллюстрация взаимодействия зубчатых передач. Для выбора зацепления, разборки редуктора и регулировочных зазоров необходима заводская документация.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['шестерня','зацепление','редуктор','трансмиссия']::text[],'https://commons.wikimedia.org/wiki/File:GearDiagram.jpg','https://commons.wikimedia.org/wiki/Special:FilePath/GearDiagram.jpg','Open Source fan','PUBLIC_DOMAIN','https://creativecommons.org/publicdomain/mark/1.0/',date '2026-11-17','illustrative'),
('alternator-wiring-example','Электросхема генератора: открытый PDF автора','document','generic',null,null,'Электрика / зарядка','Авторская схема генератора доступна по внешней ссылке. Перед применением сверяйте схему возбуждения и обозначения клемм с установленным генератором, не используйте её как заводскую распиновку.','Учебная иллюстрация принципа работы, НЕ заводская схема конкретной машины. Не применять для выбора контактов, давления, моментов затяжки или ремонта тормозов без подтверждённой документации производителя по VIN.',array['генератор','провода','зарядка','b+','d+','электросхема']::text[],'https://commons.wikimedia.org/wiki/File:AANSLUITSCHEMA_ALTERNATOR-geconverteerd(1).pdf',null,'IstasRené','CC-BY-SA-4.0','https://creativecommons.org/licenses/by-sa/4.0/',date '2026-11-17','illustrative'),
('scania-bodybuilder','Scania: официальный портал для изготовителей надстроек','manufacturer_portal','manufacturer','Scania',null,'Электрика / шасси','Официальные инструкции Scania по интеграции надстроек. Состав доступа и применимость проверяются на самом портале. Это ссылка, TrackSOS не перепубликует чертежи или распиновки.','Официальная ссылка, но не лицензия на копирование. Доступ может требовать регистрации или оплаты; применимость подтверждается по VIN на стороне производителя.',array['scania','кузов','электрика','шасси','bodybuilder','документация']::text[],'https://bodybuilder.scania.com/trucks/en/home.html',null,'Scania (official portal)','LINK_ONLY',null,date '2026-11-17','portal_link'),
('volvo-bodybuilder','Volvo Trucks: официальная техническая документация Body Builder','manufacturer_portal','manufacturer','Volvo',null,'Электрика / шасси','Официальный североамериканский портал Volvo с разделами по электрике, тормозам, шасси и трансмиссии. Модели/экостандарты могут отличаться от европейских Volvo FH: сверять год, VIN и регион.','Официальная ссылка, но не лицензия на копирование. Доступ может требовать регистрации или оплаты; применимость подтверждается по VIN на стороне производителя.',array['volvo','fh','vcu','схемы','bodybuilder','тормоза']::text[],'https://www.volvotrucks.ca/en-ca/parts-and-services/services/body-builder-support/manuals/',null,'Volvo (official portal)','LINK_ONLY',null,date '2026-11-17','portal_link'),
('man-service-rmi','MAN: портал ремонта, диагностики и технических руководств','manufacturer_portal','manufacturer','MAN',null,'Диагностика / ремонт','Официальный MAN Service Portal. Бесплатная регистрация не означает бесплатный доступ к каждой инструкции; часть материалов требует платной подписки и VIN.','Официальная ссылка, но не лицензия на копирование. Доступ может требовать регистрации или оплаты; применимость подтверждается по VIN на стороне производителя.',array['man','rmi','диагностика','электрика','ремонт','коды']::text[],'https://www.man.eu/global/en/services-accessories/workshop-services/workshop-information/workshop-portal.html',null,'MAN (official portal)','LINK_ONLY',null,date '2026-11-17','portal_link'),
('daf-rmi-portal','DAF RMI: электрические схемы и поиск по VIN','manufacturer_portal','manufacturer','DAF',null,'Диагностика / ремонт','Официальная система DAF RMI содержит схемы проводки, DTC и инструкции; для доступа необходим PACCAR.net и оплаченный период. TrackSOS не хранит и не копирует эти материалы.','Официальная ссылка, но не лицензия на копирование. Доступ может требовать регистрации или оплаты; применимость подтверждается по VIN на стороне производителя.',array['daf','rmi','paccar','dtc','схемы','vin','xf']::text[],'https://rmi.daf.com/en/standard-navigation/rmi-selection-methodes/select-information-type',null,'DAF (official portal)','LINK_ONLY',null,date '2026-11-17','portal_link'),
('renault-bodybuilder','Renault Trucks: официальный портал документации для надстроек','manufacturer_portal','manufacturer','Renault',null,'Электрика / шасси','Портал Renault Trucks Bodybuilder с регистрацией и документами по идентификаторам автомобиля. Не является общедоступной базой распиновок и не гарантирует наличие руководств для Renault Premium DSI 2010.','Официальная ссылка, но не лицензия на копирование. Доступ может требовать регистрации или оплаты; применимость подтверждается по VIN на стороне производителя.',array['renault','premium','dsi','электрика','bodybuilder','шасси']::text[],'https://bodybuilder.renault-trucks.com/en/register',null,'Renault (official portal)','LINK_ONLY',null,date '2026-11-17','portal_link') 
